def grant_app_permissions() -> None:
    """F6: tài khoản ứng dụng chỉ SELECT, INSERT trên bảng chỉ ghi thêm; UPDATE/DELETE chỉ trên bảng được sửa."""
    statements = [
        f"GRANT SELECT, INSERT ON {', '.join(APPEND_ONLY + MUTABLE)} TO {APP_ROLE}",
        f"GRANT UPDATE, DELETE ON {', '.join(MUTABLE)} TO {APP_ROLE}",
        f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO {APP_ROLE}",
    ]
    body = " ".join(f"EXECUTE '{s}';" for s in statements)
    # Bỏ qua nếu chưa có role (ví dụ DB không tạo bằng docker-compose)
    op.execute(f"DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{APP_ROLE}') THEN {body} END IF; END $$")


